package uy.metapunto;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.*;
import javax.xml.parsers.*;
import javax.xml.transform.*;
import javax.xml.transform.dom.DOMSource;
import javax.xml.transform.stream.StreamResult;
import org.w3c.dom.*;
import com.drew.imaging.ImageMetadataReader;
import com.drew.metadata.*;
import com.tom_roush.pdfbox.pdmodel.*;
import com.tom_roush.pdfbox.cos.*;

final class Engine {
 static String ext(String n){int p=n.lastIndexOf('.');return p<0?"":n.substring(p+1).toLowerCase(Locale.ROOT);}
 static boolean office(String n){return Arrays.asList("docx","xlsx","pptx").contains(ext(n));}
 static boolean supported(String n){return office(n)||Arrays.asList("jpg","jpeg","png","webp","pdf").contains(ext(n));}
 static void copy(InputStream i,OutputStream o)throws IOException{byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1)o.write(b,0,n);}
 static byte[] bytes(InputStream in,int max)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(o.size()+n>max)throw new IOException("Contenido expandido demasiado grande");o.write(b,0,n);}return o.toByteArray();}
 static Document xml(byte[] b)throws Exception{
 String probe=new String(b,StandardCharsets.UTF_8).replace("\u0000", "").toUpperCase(Locale.ROOT);
 if(probe.contains("<!DOCTYPE")||probe.contains("<!ENTITY"))throw new org.xml.sax.SAXException("DOCTYPE y entidades no permitidos");
 DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setExpandEntityReferences(false);
 for(String feature:Arrays.asList("http://xml.org/sax/features/external-general-entities","http://xml.org/sax/features/external-parameter-entities")){try{f.setFeature(feature,false);}catch(ParserConfigurationException ignored){}}
 try{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);}catch(ParserConfigurationException ignored){}
 DocumentBuilder builder=f.newDocumentBuilder();builder.setEntityResolver((publicId,systemId)->{throw new org.xml.sax.SAXException("Entidad externa bloqueada");});return builder.parse(new ByteArrayInputStream(b));
 }
 static String inspect(File f,String name)throws Exception{StringBuilder s=new StringBuilder();s.append("Tamaño: ").append(f.length()).append(" bytes\n");
 if(ext(name).equals("pdf")){try(PDDocument d=PDDocument.load(f)){s.append("Páginas: ").append(d.getNumberOfPages()).append('\n');COSDictionary info=d.getDocumentInformation().getCOSObject();for(COSName k:info.keySet())s.append(k.getName()).append(": ").append(info.getDictionaryObject(k)).append('\n');if(d.getDocumentCatalog().getMetadata()!=null){try(InputStream in=d.getDocumentCatalog().getMetadata().createInputStream()){s.append("XMP:\n").append(new String(bytes(in,2*1024*1024),StandardCharsets.UTF_8));}}s.append("\nAlcance: propiedades y XMP del documento. No se inspeccionan todas las imágenes, adjuntos ni objetos internos.\n");}}
 else if(office(name)){try(ZipFile z=new ZipFile(f)){Enumeration<? extends ZipEntry> e=z.entries();while(e.hasMoreElements()){ZipEntry item=e.nextElement();if(item.getName().startsWith("docProps/")&&item.getName().endsWith(".xml")){s.append('\n').append(item.getName()).append('\n');try(InputStream in=z.getInputStream(item)){Document d=xml(bytes(in,2*1024*1024));leaves(d.getDocumentElement(),s);}}}}s.append("\nAlcance: propiedades de Office. Comentarios, revisiones y archivos incrustados pueden conservar datos personales.\n");}
 else{try{Metadata m=ImageMetadataReader.readMetadata(f);int count=0;for(Directory d:m.getDirectories()){s.append('\n').append('[').append(d.getName()).append("]\n");for(Tag t:d.getTags()){s.append(t.getTagName()).append(": ").append(t.getDescription()).append('\n');count++;}for(String error:d.getErrors())s.append("Aviso: ").append(error).append('\n');}if(count==0)s.append("No se encontraron campos con este lector.\n");}catch(Exception e){s.append("Inspección no disponible o archivo inválido: ").append(e.getMessage()).append('\n');}}
 s.append("\nAusencia de datos ≠ ausencia de rastros. IP y GPS solo si están presentes. No se verifica procedencia de IA ni marcas invisibles.\n");if(!supported(name))s.append("Este formato no tiene limpieza habilitada.\n");return s.toString();}
 static void leaves(Element e,StringBuilder s){NodeList nodes=e.getChildNodes();boolean child=false;for(int i=0;i<nodes.getLength();i++)if(nodes.item(i) instanceof Element){child=true;leaves((Element)nodes.item(i),s);}if(!child)s.append(e.getNodeName()).append(": ").append(e.getTextContent()).append('\n');}
 static void clean(File in,File out,String name)throws Exception{
 if(office(name)){cleanOffice(in,out);return;}
 if(ext(name).equals("pdf")){try(PDDocument d=PDDocument.load(in)){if(d.isEncrypted())throw new IOException("PDF cifrado: no compatible en esta versión");PDDocumentInformation info=new PDDocumentInformation();for(String key:Arrays.asList("Author","Title","Subject","Keywords","Creator","Producer"))info.setCustomMetadataValue(key,".");d.setDocumentInformation(info);d.getDocumentCatalog().setMetadata(null);Set<COSBase> seen=Collections.newSetFromMap(new IdentityHashMap<>());scrub(d.getDocument().getTrailer(),seen);d.save(out);}return;}
 byte[] b;try(InputStream i=new FileInputStream(in)){b=bytes(i,40*1024*1024);}byte[] result;
 switch(ext(name)){case "jpg":case "jpeg":result=jpeg(b);break;case "png":result=png(b);break;case "webp":result=webp(b);break;default:throw new IOException("Formato no compatible");}try(OutputStream o=new FileOutputStream(out)){o.write(result);}
 }
 static void scrub(COSBase b,Set<COSBase> seen){if(b==null||!seen.add(b))return;if(b instanceof COSObject){scrub(((COSObject)b).getObject(),seen);return;}if(b instanceof COSDictionary){COSDictionary d=(COSDictionary)b;d.removeItem(COSName.METADATA);for(COSName k:new ArrayList<>(d.keySet()))scrub(d.getItem(k),seen);}else if(b instanceof COSArray)for(COSBase item:(COSArray)b)scrub(item,seen);}
 static void cleanOffice(File in,File out)throws Exception{try(ZipFile z=new ZipFile(in);ZipOutputStream o=new ZipOutputStream(new FileOutputStream(out))){Enumeration<? extends ZipEntry> entries=z.entries();long total=0;int count=0;while(entries.hasMoreElements()){ZipEntry e=entries.nextElement();if(++count>10000)throw new IOException("Demasiadas partes");if(e.isDirectory())continue;byte[] b;try(InputStream i=z.getInputStream(e)){b=bytes(i,40*1024*1024);}total+=b.length;if(total>100L*1024*1024)throw new IOException("Documento expandido supera 100 MB");String path=e.getName();if(path.startsWith("docProps/")&&path.endsWith(".xml")){Document d=xml(b);dotProperties(d.getDocumentElement());Transformer t=TransformerFactory.newInstance().newTransformer();ByteArrayOutputStream a=new ByteArrayOutputStream();t.transform(new DOMSource(d),new StreamResult(a));b=a.toByteArray();}o.putNextEntry(new ZipEntry(path));o.write(b);o.closeEntry();}}}
 static void dotProperties(Element root){for(Node n=root.getFirstChild();n!=null;){Node next=n.getNextSibling();if(n instanceof Element){Element e=(Element)n;String local=e.getLocalName();if("property".equals(local)){e.setAttribute("name",".");while(e.hasChildNodes())e.removeChild(e.getFirstChild());Element v=e.getOwnerDocument().createElementNS("http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes","vt:lpwstr");v.setTextContent(".");e.appendChild(v);}else if(Arrays.asList("title","subject","creator","keywords","description","lastModifiedBy","category","contentStatus","identifier","language","version","Application","AppVersion","Company","Manager","Template","HyperlinkBase").contains(local))e.setTextContent(".");else root.removeChild(e);}n=next;}}
 static byte[] jpeg(byte[] b)throws IOException{if(b.length<4||(b[0]&255)!=255||(b[1]&255)!=216)throw new IOException("No es JPEG");ByteArrayOutputStream o=new ByteArrayOutputStream();o.write(b,0,2);o.write(new byte[]{(byte)255,(byte)254,0,3,46});int p=2;while(p<b.length){int start=p;if((b[p++]&255)!=255)throw new IOException("JPEG inválido");while(p<b.length&&(b[p]&255)==255)p++;if(p>=b.length)throw new IOException("JPEG truncado");int marker=b[p++]&255;if(marker==218){o.write(b,start,b.length-start);return o.toByteArray();}if(marker==217){o.write(b,start,p-start);return o.toByteArray();}if(marker==1||(marker>=208&&marker<=215)){o.write(b,start,p-start);continue;}if(p+2>b.length)throw new IOException("JPEG truncado");int len=((b[p]&255)<<8)|(b[p+1]&255);if(len<2||p+len>b.length)throw new IOException("Longitud JPEG inválida");boolean remove=(marker>=225&&marker<=239)||marker==254;if(!remove)o.write(b,start,p+len-start);p+=len;}throw new IOException("JPEG sin imagen");}
 static int be(byte[]b,int p){return ((b[p]&255)<<24)|((b[p+1]&255)<<16)|((b[p+2]&255)<<8)|(b[p+3]&255);}
 static void chunk(DataOutputStream o,String type,byte[] data)throws IOException{byte[] t=type.getBytes(StandardCharsets.US_ASCII);o.writeInt(data.length);o.write(t);o.write(data);CRC32 c=new CRC32();c.update(t);c.update(data);o.writeInt((int)c.getValue());}
 static byte[] png(byte[]b)throws IOException{byte[] sig={(byte)137,80,78,71,13,10,26,10};if(b.length<8||!Arrays.equals(Arrays.copyOf(b,8),sig))throw new IOException("No es PNG");ByteArrayOutputStream a=new ByteArrayOutputStream();DataOutputStream o=new DataOutputStream(a);o.write(sig);int p=8;boolean end=false;while(p+12<=b.length){int n=be(b,p);if(n<0||n>b.length-p-12)throw new IOException("PNG inválido");String type=new String(b,p+4,4,StandardCharsets.US_ASCII);if(type.equals("acTL"))throw new IOException("PNG animado no compatible");if(Arrays.asList("IHDR","PLTE","IDAT","IEND","tRNS","gAMA","cHRM","sRGB","sBIT").contains(type)){if(type.equals("IEND"))chunk(o,"tEXt","Comment\u0000.".getBytes(StandardCharsets.ISO_8859_1));o.write(b,p,n+12);}p+=n+12;if(type.equals("IEND")){end=true;break;}}if(!end)throw new IOException("PNG incompleto");return a.toByteArray();}
 static int le(byte[]b,int p){return Integer.reverseBytes(be(b,p));}
 static byte[] webp(byte[]b)throws IOException{if(b.length<12||!new String(b,0,4,StandardCharsets.US_ASCII).equals("RIFF")||!new String(b,8,4,StandardCharsets.US_ASCII).equals("WEBP"))throw new IOException("No es WebP");ByteArrayOutputStream a=new ByteArrayOutputStream();a.write(b,0,12);int p=12;while(p+8<=b.length){int n=le(b,p+4);if(n<0||n>b.length-p-8-(n&1))throw new IOException("WebP inválido");String t=new String(b,p,4,StandardCharsets.US_ASCII);if(t.equals("ANIM")||t.equals("ANMF"))throw new IOException("WebP animado no compatible");if(Arrays.asList("VP8 ","VP8L","VP8X","ALPH").contains(t)){byte[] c=Arrays.copyOfRange(b,p,p+8+n+(n&1));if(t.equals("VP8X")&&n>=1)c[8]=(byte)(c[8]&~(0x20|0x08|0x04));a.write(c);}p+=8+n+(n&1);}// WebP: do not add an XMP chunk to a simple bitstream lacking VP8X.
 byte[] r=a.toByteArray();int size=r.length-8;for(int j=0;j<4;j++)r[4+j]=(byte)(size>>>(8*j));return r;}
}
